begin;create extension if not exists pgtap with schema extensions;select plan(24);
create schema if not exists test;create function test.login(id uuid) returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub',id::text,true);perform set_config('request.jwt.claim.role','authenticated',true);end$$;
set local role anon;select is((select count(*) from public.customers),0::bigint,'anonymous reads no customers');reset role;
set local role authenticated;select test.login('00000000-0000-4000-8000-000000000001');select is((select count(*) from customers),1::bigint,'customer A sees self');select is((select count(*) from customers where id='20000000-0000-4000-8000-000000000002'),0::bigint,'customer A cannot read B');select is((select count(*) from routes),0::bigint,'customer sees no CRM routes');select is((select count(*) from service_visits where customer_id='20000000-0000-4000-8000-000000000002'),0::bigint,'customer sees no other visits');update customers set full_name='attack' where id='20000000-0000-4000-8000-000000000002';select is((select count(*) from customers where full_name='attack'),0::bigint,'customer cannot modify B');
select test.login('00000000-0000-4000-8000-000000000011');update service_plan_versions set base_price_cents=1;select is((select count(*) from service_plan_versions where base_price_cents=1),0::bigint,'dispatcher cannot price');update subscriptions set service_status='attack';select is((select count(*) from subscriptions where service_status='attack'),0::bigint,'dispatcher cannot subscriptions');update referral_credits set remaining_cents=0;select is((select count(*) from referral_credits where remaining_cents=0),0::bigint,'dispatcher cannot credits');delete from staff_roles;select is((select count(*) from staff_roles where user_id=auth.uid()),1::bigint,'dispatcher cannot delete own role');
select test.login('00000000-0000-4000-8000-000000000012');select is((select count(*) from routes),1::bigint,'assigned tech sees route');select is((select count(*) from service_visits),1::bigint,'assigned tech sees one visit');select is((select count(*) from customers),1::bigint,'tech sees only assigned customer');select is((select count(*) from customers where id='20000000-0000-4000-8000-000000000002'),0::bigint,'tech cannot browse unrelated customer');select is((select count(*) from subscriptions),0::bigint,'tech sees no finances');select throws_ok($$update service_visits set assigned_technician_id='00000000-0000-4000-8000-000000000013' where id='80000000-0000-4000-8000-000000000001'$$,'new row violates row-level security policy for table "service_visits"','tech cannot reassign');
select test.login('00000000-0000-4000-8000-000000000013');select is((select count(*) from routes),0::bigint,'unassigned tech sees no routes');select is((select count(*) from service_visits),0::bigint,'unassigned tech sees no visits');select is((select count(*) from service_addresses),0::bigint,'unassigned tech sees no customer address');
select test.login('00000000-0000-4000-8000-000000000010');select is((select count(*) from customers),4::bigint,'administrator sees all customers');select lives_ok($$update customers set phone=phone where id='20000000-0000-4000-8000-000000000002'$$,'admin may update customer');select ok((select count(*)>0 from audit_events where entity_id='20000000-0000-4000-8000-000000000002' and action='UPDATE'),'protected mutation audited');select throws_ok($$update service_visits set status='completed',cleaning_confirmed=true,bins_returned=true where id='80000000-0000-4000-8000-000000000002';set constraints enforce_visit_completion immediate$$,'Completion requires before/after photos, cleaning, and bin return or authorized exception','photos enforced');select lives_ok($$update service_visits set status='completed',completed_at=now() where id='80000000-0000-4000-8000-000000000001';set constraints enforce_visit_completion immediate$$,'documented visit completes');
select * from finish();rollback;
